// SPDX-License-Identifier: MIT
pragma solidity 0.8.36;

// ╔══════════════════════════════════════════════════════════════════════════╗
// ║  FeeSplitter                                                             ║
// ║                                                                          ║
// ║  Pièce manquante référencée par MemeCoinFactory.sol (import non résolu   ║
// ║  dans Factory.md — ce fichier la complète).                              ║
// ║                                                                          ║
// ║  Déployé une fois par lancement (`new FeeSplitter(creator, platform)`,   ║
// ║  signature imposée par MemeCoinFactory.launchToken()). Reçoit les fees   ║
// ║  de swap collectées par le LiquidityCustodian associé (en token0 et/ou   ║
// ║  token1 selon le sens des trades — un `collect()` Uniswap V3 peut        ║
// ║  renvoyer les deux) et les répartit 50/50 entre :                        ║
// ║    - `creator`  : msg.sender du launchToken() original (immutable)      ║
// ║    - `platform` : trésorerie du studio (immutable, fixée UNE FOIS au     ║
// ║      déploiement de MemeCoinFactory — voir MASTER_REFERENCE.md §2.3 —    ║
// ║      et propagée à chaque FeeSplitter déployé par la factory)            ║
// ║                                                                          ║
// ║  FIX (Critical) : `platform` était une constante hardcodée à address(0)  ║
// ║  ("TODO: renseigner avant mainnet"), jamais suivie d'effet — chaque      ║
// ║  release() aurait donc brûlé silencieusement la moitié des fees vers     ║
// ║  l'adresse zéro. Elle devient un paramètre de constructeur OBLIGATOIRE   ║
// ║  (require != address(0)) : impossible de déployer sans la renseigner,   ║
// ║  au lieu de déployer avec succès et perdre les fonds plus tard.          ║
// ║                                                                          ║
// ║  release(token) est permissionless : n'importe qui peut déclencher la    ║
// ║  répartition d'un token ERC20 donné détenu par ce contrat — symétrique   ║
// ║  avec collect() sur le LiquidityCustodian, qui est déjà permissionless.  ║
// ║                                                                          ║
// ║  ⚠️  NON AUDITÉ.                                                         ║
// ╚══════════════════════════════════════════════════════════════════════════╝

interface IERC20Splitter {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 value) external returns (bool);
}

contract FeeSplitter {
    // FIX (H002 candidate — REENTRANCY) : release(token) accepte une adresse
    // `token` ARBITRAIRE (pas seulement le memecoin ou WETH) et enchaîne
    // balanceOf() + deux transfer() externes, sans verrou auparavant. Un
    // `token` malveillant fourni par un appelant pourrait tenter de
    // réentrer pendant son propre transfer()/balanceOf(). Aucune valeur
    // réelle (creator/platform sont fixes) ne peut être détournée par ce
    // biais, mais un verrou coûte presque rien et ferme la question
    // proprement plutôt que de compter sur cette analyse.
    uint256 private _reentrancyStatus = 1;
    error ReentrancyGuardReentrantCall();
    modifier nonReentrant() {
        if (_reentrancyStatus == 2) revert ReentrancyGuardReentrantCall();
        _reentrancyStatus = 2;
        _;
        _reentrancyStatus = 1;
    }

    /// @notice Créateur du token (msg.sender du launchToken() d'origine).
    ///         Reçoit 50% de chaque release(). Fixé une fois, non modifiable.
    address public immutable creator;

    /// @notice Trésorerie du studio. Reçoit 50% de chaque release(). Fixée
    ///         une fois au déploiement, propagée depuis MemeCoinFactory —
    ///         voir MASTER_REFERENCE.md §2.3 (0x3a7a125D23689d8F7f218B28f19305d33b6c9B18).
    address public immutable platform;

    event Released(address indexed token, uint256 creatorAmount, uint256 platformAmount);

    constructor(address creator_, address platform_) {
        require(creator_ != address(0), "FeeSplitter: invalid creator");
        require(platform_ != address(0), "FeeSplitter: invalid platform");
        creator = creator_;
        platform = platform_;
    }

    /// @notice Distribue tout le solde actuel d'un token ERC20 détenu par ce
    ///         contrat, 50/50 entre `creator` et `PLATFORM`. Permissionless —
    ///         n'importe qui peut appeler cette fonction, seules les
    ///         destinations sont fixes.
    /// @param token Adresse du token à répartir (le token du memecoin ou
    ///              WETH, selon ce que collect() a renvoyé).
    function release(address token) external nonReentrant {
        uint256 balance = IERC20Splitter(token).balanceOf(address(this));
        require(balance > 0, "FeeSplitter: nothing to release");

        uint256 creatorAmount = balance / 2;
        uint256 platformAmount = balance - creatorAmount; // reste l'arrondi si balance impair

        require(IERC20Splitter(token).transfer(creator, creatorAmount), "FeeSplitter: creator transfer failed");
        require(IERC20Splitter(token).transfer(platform, platformAmount), "FeeSplitter: platform transfer failed");

        emit Released(token, creatorAmount, platformAmount);
    }
}
